"""Dependency-free Lightroom-style image and video adjustments."""

from __future__ import annotations

import math
from collections.abc import Mapping
from typing import Any

import torch
import torch.nn.functional as functional

from ..core.video_api import components_for_video, make_video_components, make_video_from_components
from .utilities import WslAnyType


HSL_ZONES = (
    ("red", 0.0),
    ("orange", 30.0),
    ("yellow", 60.0),
    ("green", 120.0),
    ("aqua", 180.0),
    ("blue", 210.0),
    ("purple", 270.0),
    ("magenta", 330.0),
)
BASE_CONTROLS = (
    "temperature", "tint", "exposure", "contrast", "highlights", "shadows",
    "whites", "blacks", "texture", "clarity", "dehaze", "vibrance", "saturation",
)
CONTROL_NAMES = BASE_CONTROLS + tuple(
    f"{zone}_{control}"
    for zone, _center in HSL_ZONES
    for control in ("hue", "saturation", "lightness")
)
STAGE_CONTROLS = {
    "light": ("exposure", "contrast", "highlights", "shadows", "whites", "blacks"),
    "color": ("temperature", "tint", "vibrance", "saturation"),
    "detail": ("texture", "clarity", "dehaze"),
    "hsl_warm": tuple(
        f"{zone}_{control}"
        for zone, _center in HSL_ZONES[:4]
        for control in ("hue", "saturation", "lightness")
    ),
    "hsl_cool": tuple(
        f"{zone}_{control}"
        for zone, _center in HSL_ZONES[4:]
        for control in ("hue", "saturation", "lightness")
    ),
}


def _normalise(values: Mapping[str, Any]) -> dict[str, float]:
    result: dict[str, float] = {}
    for name in CONTROL_NAMES:
        try:
            value = float(values.get(name, 0.0))
        except (TypeError, ValueError):
            value = 0.0
        result[name] = value if math.isfinite(value) else 0.0
    return result


def _has_adjustments(values: Mapping[str, Any]) -> bool:
    return any(abs(float(values.get(name, 0.0))) > 1e-8 for name in CONTROL_NAMES)


def _rgb_to_hsl(rgb: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
    red, green, blue = rgb.unbind(dim=1)
    maximum = torch.maximum(torch.maximum(red, green), blue)
    minimum = torch.minimum(torch.minimum(red, green), blue)
    delta = maximum - minimum
    lightness = (maximum + minimum) * 0.5
    denominator = (1.0 - (2.0 * lightness - 1.0).abs()).clamp_min(1e-6)
    saturation = torch.where(delta > 1e-6, delta / denominator, torch.zeros_like(delta))

    hue = torch.zeros_like(delta)
    valid = delta > 1e-6
    hue = torch.where(
        (maximum == red) & valid,
        ((green - blue) / delta.clamp_min(1e-6)).remainder(6.0),
        hue,
    )
    hue = torch.where((maximum == green) & valid, (blue - red) / delta.clamp_min(1e-6) + 2.0, hue)
    hue = torch.where((maximum == blue) & valid, (red - green) / delta.clamp_min(1e-6) + 4.0, hue)
    return hue.remainder(6.0) / 6.0, saturation.clamp(0.0, 1.0), lightness.clamp(0.0, 1.0)


def _hsl_to_rgb(hue: torch.Tensor, saturation: torch.Tensor, lightness: torch.Tensor) -> torch.Tensor:
    saturation = saturation.clamp(0.0, 1.0)
    lightness = lightness.clamp(0.0, 1.0)
    chroma = (1.0 - (2.0 * lightness - 1.0).abs()) * saturation
    hue6 = hue.remainder(1.0) * 6.0
    first = chroma * (1.0 - ((hue6.remainder(2.0)) - 1.0).abs())
    match = lightness - chroma * 0.5
    zero = torch.zeros_like(chroma)
    red = torch.where(
        hue6 < 1.0,
        chroma,
        torch.where(hue6 < 2.0, first, torch.where(hue6 < 4.0, zero, torch.where(hue6 < 5.0, first, chroma))),
    )
    green = torch.where(hue6 < 1.0, first, torch.where(hue6 < 3.0, chroma, torch.where(hue6 < 4.0, first, zero)))
    blue = torch.where(hue6 < 2.0, zero, torch.where(hue6 < 3.0, first, torch.where(hue6 < 5.0, chroma, torch.where(hue6 < 6.0, first, zero))))
    return torch.stack((red + match, green + match, blue + match), dim=1)


def adjust_rgb(rgb: torch.Tensor, values: Mapping[str, Any]) -> torch.Tensor:
    params = _normalise(values)
    if not _has_adjustments(params):
        return rgb

    output = rgb.to(dtype=torch.float32).clone()
    temperature = params["temperature"] / 100.0
    tint = params["tint"] / 100.0
    output[:, 0] += temperature * 0.16 + tint * 0.04
    output[:, 1] -= tint * 0.10
    output[:, 2] += -temperature * 0.16 + tint * 0.04

    output *= 2.0 ** params["exposure"]
    contrast = max(-100.0, min(100.0, params["contrast"])) / 100.0
    output = (output - 0.5) * (1.0 + contrast) + 0.5

    luminance = output[:, 0] * 0.2126 + output[:, 1] * 0.7152 + output[:, 2] * 0.0722
    highlight_weight = ((luminance - 0.45) / 0.55).clamp(0.0, 1.0).pow(1.5)
    shadow_weight = ((0.55 - luminance) / 0.55).clamp(0.0, 1.0).pow(1.5)
    output += params["highlights"] / 100.0 * highlight_weight.unsqueeze(1) * 0.28
    output += params["shadows"] / 100.0 * shadow_weight.unsqueeze(1) * 0.28
    output += params["whites"] / 100.0 * 0.10
    output += params["blacks"] / 100.0 * 0.10

    if abs(params["texture"]) > 1e-8 or abs(params["clarity"]) > 1e-8:
        smooth = functional.avg_pool2d(output, kernel_size=3, stride=1, padding=1)
        detail = output - smooth
        output += detail * (params["texture"] / 100.0 * 1.25 + params["clarity"] / 100.0 * 0.85)

    if abs(params["dehaze"]) > 1e-8:
        luma_mean = luminance.mean(dim=(1, 2), keepdim=True)
        dehaze = params["dehaze"] / 100.0
        output = (output - luma_mean.unsqueeze(1)) * (1.0 + dehaze * 0.35) + luma_mean.unsqueeze(1) + dehaze * 0.04

    hue, saturation, lightness = _rgb_to_hsl(output)
    saturation += params["vibrance"] / 100.0 * (1.0 - saturation) * 0.75
    saturation *= 1.0 + params["saturation"] / 100.0
    for zone, center_degrees in HSL_ZONES:
        center = center_degrees / 360.0
        distance = (hue - center + 0.5).remainder(1.0) - 0.5
        weight = (1.0 - distance.abs() / (45.0 / 360.0)).clamp(0.0, 1.0).pow(1.5)
        hue += weight * params[f"{zone}_hue"] / 100.0 * (25.0 / 360.0)
        saturation += weight * params[f"{zone}_saturation"] / 100.0 * 0.50
        lightness += weight * params[f"{zone}_lightness"] / 100.0 * 0.25
    return _hsl_to_rgb(hue, saturation, lightness).clamp(0.0, 1.0)


def adjust_image(image: torch.Tensor, values: Mapping[str, Any]) -> torch.Tensor:
    if not isinstance(image, torch.Tensor) or image.ndim != 4:
        raise TypeError("调色图像必须使用 ComfyUI 的 [batch, height, width, channels] 格式")
    channels = int(image.shape[-1])
    if channels < 3:
        raise ValueError("调色需要至少包含 RGB 三个通道")
    if not _has_adjustments(values):
        return image
    with torch.no_grad():
        rgb = adjust_rgb(image[..., :3].movedim(-1, 1), values).movedim(1, -1)
        if channels > 3:
            rgb = torch.cat((rgb, image[..., 3:]), dim=-1)
        return rgb.to(dtype=image.dtype)


def adjust_media(media: Any, values: Mapping[str, Any]) -> Any:
    params = _normalise(values)
    if isinstance(media, torch.Tensor):
        return adjust_image(media, params)
    components = components_for_video(media)
    if not _has_adjustments(params):
        return media
    images = adjust_image(components.images, params)
    output_components = make_video_components(
        images,
        audio=getattr(components, "audio", None),
        frame_rate=getattr(components, "frame_rate", None),
        metadata=getattr(components, "metadata", None),
        alpha=getattr(components, "alpha", None),
    )
    return make_video_from_components(media, output_components)


def _control_spec(name: str):
    if name == "exposure":
        return ("FLOAT", {"default": 0.0, "min": -5.0, "max": 5.0, "step": 0.01})
    return ("FLOAT", {"default": 0.0, "min": -100.0, "max": 100.0, "step": 0.01})


def _image_input_types(input_name: str) -> dict:
    controls = {name: _control_spec(name) for name in CONTROL_NAMES}
    input_spec = ("IMAGE",) if input_name == "image" else ("VIDEO",)
    return {"required": {input_name: input_spec, **controls}}


class WyslLightroomImage:
    CATEGORY = "Wysl/Lightroom 调色"
    FUNCTION = "adjust"
    RETURN_TYPES = ("IMAGE",)
    RETURN_NAMES = ("图像",)
    DESCRIPTION = "VAE 解码后应用完整 Lightroom 调色，所有控件默认值为 0。"

    @classmethod
    def INPUT_TYPES(cls):
        return _image_input_types("image")

    @staticmethod
    def adjust(image, **values):
        return (adjust_image(image, values),)


class WyslLightroomVideo:
    CATEGORY = "Wysl/Lightroom 调色"
    FUNCTION = "adjust"
    RETURN_TYPES = ("VIDEO",)
    RETURN_NAMES = ("视频",)
    DESCRIPTION = "对 ComfyUI VIDEO 的全部帧应用 Lightroom 调色，所有控件默认值为 0。"

    @classmethod
    def INPUT_TYPES(cls):
        return _image_input_types("video")

    @staticmethod
    def adjust(video, **values):
        return (adjust_media(video, values),)


def _stage_input_types(stage: str) -> dict:
    controls = {name: _control_spec(name) for name in STAGE_CONTROLS[stage]}
    return {"required": {"media": (WslAnyType,), **controls}}


class _LightroomStage:
    CATEGORY = "Wysl/Lightroom 调色"
    FUNCTION = "adjust"
    RETURN_TYPES = (WslAnyType,)
    RETURN_NAMES = ("图像或视频",)

    @classmethod
    def INPUT_TYPES(cls):
        return _stage_input_types(cls.STAGE_KEY)

    @staticmethod
    def _adjust(media, **values):
        return (adjust_media(media, values),)

    def adjust(self, media, **values):
        return self._adjust(media, **values)


class WyslLightroomLight(_LightroomStage):
    STAGE_KEY = "light"
    DESCRIPTION = "基础明暗调节，可与其他 Lightroom 调色节点串联。"


class WyslLightroomColor(_LightroomStage):
    STAGE_KEY = "color"
    DESCRIPTION = "色温、色调、鲜艳度和饱和度调节，可与其他 Lightroom 调色节点串联。"


class WyslLightroomDetail(_LightroomStage):
    STAGE_KEY = "detail"
    DESCRIPTION = "纹理、清晰度和去朦胧调节，可与其他 Lightroom 调色节点串联。"


class WyslLightroomHSLWarm(_LightroomStage):
    STAGE_KEY = "hsl_warm"
    DESCRIPTION = "红、橙、黄、绿四个色区的 HSL 调节，可与其他 Lightroom 调色节点串联。"


class WyslLightroomHSLCool(_LightroomStage):
    STAGE_KEY = "hsl_cool"
    DESCRIPTION = "青、蓝、紫、洋红四个色区的 HSL 调节，可与其他 Lightroom 调色节点串联。"


def _grain_kernel_size(value: float) -> int:
    """把 0-100 滑块映射为奇数模糊核大小。

    value=0   → 1  (不模糊，细颗粒)
    value=25  → ~4 (Lightroom 默认)
    value=100 → 13 (很粗的斑块)
    """
    size = int(round(value / 25.0 * 3.0)) + 1
    if size % 2 == 0:
        size += 1
    return max(1, size)


def _apply_grain(rgb: torch.Tensor, amount: float, size: float, roughness: float) -> torch.Tensor:
    """应用 Lightroom Effects→Grain 风格的胶片颗粒。

    rgb:       [B, 3, H, W] float32，取值 [0, 1]
    amount:    0-100  颗粒强度（0=无颗粒）
    size:      0-100  颗粒尺寸（25=默认）
    roughness: 0-100  颗粒粗糙度（100=锐利数字噪声，0=柔和斑块；100=默认）

    颗粒在 luma 维度上叠加，并通过两层 `avg_pool2d` 把 0-100 滑块映射为
    模糊核大小，最后按 amount 缩放到 0-0.18 区间。
    """
    if amount <= 0:
        return rgb
    noise = torch.randn(
        rgb.shape[0], 1, rgb.shape[2], rgb.shape[3],
        device=rgb.device, dtype=rgb.dtype,
    )
    size_k = _grain_kernel_size(size)
    if size_k > 1:
        noise = functional.avg_pool2d(noise, kernel_size=size_k, stride=1, padding=size_k // 2)
    rough_k = _grain_kernel_size(100.0 - roughness)
    if rough_k > 1:
        noise = functional.avg_pool2d(noise, kernel_size=rough_k, stride=1, padding=rough_k // 2)
    noise = noise - noise.mean()
    noise = noise / noise.std().clamp_min(1e-6)
    strength = (amount / 100.0) * 0.18
    return (rgb + noise * strength).clamp(0.0, 1.0)


class WyslLightroomGrain:
    CATEGORY = "Wysl/Lightroom 调色"
    FUNCTION = "apply_grain"
    RETURN_TYPES = ("IMAGE",)
    RETURN_NAMES = ("图像",)
    DESCRIPTION = "VAE 解码后应用 Lightroom 颗粒（噪点）效果；三个控件默认数量 20 / 大小 0 / 粗糙度 0。"

    @classmethod
    def INPUT_TYPES(cls):
        return {
            "required": {
                "image": ("IMAGE",),
                "amount": ("FLOAT", {"default": 20.0, "min": 0.0, "max": 100.0, "step": 0.5}),
                "size": ("FLOAT", {"default": 0.0, "min": 0.0, "max": 100.0, "step": 0.5}),
                "roughness": ("FLOAT", {"default": 0.0, "min": 0.0, "max": 100.0, "step": 0.5}),
            }
        }

    @staticmethod
    def apply_grain(image, amount, size, roughness):
        if not isinstance(image, torch.Tensor) or image.ndim != 4:
            raise TypeError("颗粒节点必须使用 ComfyUI 的 [batch, height, width, channels] 格式")
        channels = int(image.shape[-1])
        if channels < 3:
            raise ValueError("颗粒节点需要至少包含 RGB 三个通道")
        with torch.no_grad():
            rgb = image[..., :3].movedim(-1, 1).to(dtype=torch.float32)
            rgb = _apply_grain(rgb, float(amount), float(size), float(roughness))
            rgb = rgb.movedim(1, -1)
            if channels > 3:
                rgb = torch.cat((rgb, image[..., 3:].to(dtype=torch.float32)), dim=-1)
            return (rgb.to(dtype=image.dtype),)


